{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE TABLE IF NOT EXISTS sleepycat_db.maplemonk.zepto_SKU_Master AS SELECT CAST(NULL AS STRING) AS EAN, skucode, category, sub_category, CAST(NULL AS NUMBER) AS GST_Rate, name, CAST(NULL AS STRING) AS HSN, CAST(NULL AS DATE) AS Product_Launch_date, CAST(NULL AS STRING) AS product_image_url, CAST(NULL AS NUMBER) AS cogs, marketplace_sku FROM sleepycat_db.maplemonk.final_sku_master; CREATE TABLE IF NOT EXISTS sleepycat_db.maplemonk.gs_qc_sku_mapping ( EAN STRING, SKU STRING, Zepto_SKU STRING, SP_from_22_Sep NUMBER, SP_till_21_Sep NUMBER, Swiggy_item_id STRING, Blinkit_item_id STRING, _airbyte_ab_id STRING, _airbyte_emitted_at TIMESTAMP, _airbyte_normalized_at TIMESTAMP, _airbyte_GS_QC_SKU_MAPPING_hashid STRING ); CREATE OR REPLACE TABLE sleepycat_db.maplemonk.sleepycat_zepto_fact_items_intermediate AS SELECT EAN, CONCAT(EAN, \"SKU Number\", city, date) AS order_item, CAST(MRP AS FLOAT) AS MRP, CITY, CAST(Date AS TIMESTAMP) AS Order_Date, \"SKU Name\" AS Product_name, \"Brand Name\" AS Brand, \"SKU Number\" AS sku_number, \"SKU Category\" AS sku_category, CAST(\"Gross Merchandise Value\" AS FLOAT) AS selling_price, \"Manufacturer ID\" AS manufacturer_id, \"SKU Sub Category\" AS SKU_Sub_Category, CAST(\"Gross Merchandise Value\" AS FLOAT) AS Gross_Selling_Value, CAST(\"Sales (Qty) - Units\" AS NUMBER) AS quantity, CAST(\"Gross Merchandise Value\" AS FLOAT) AS Gross_Merchandise_Value FROM sleepycat_db.maplemonk.zepto_sleepycat_sales ; CREATE OR REPLACE TABLE sleepycat_db.maplemonk.sleepycat_zepto_fact_items AS SELECT z.*, z.quantity * tv.taxable_value AS Selling_Price_final, UPPER( COALESCE( p.name , REPLACE(LOWER(z.Product_name), \'Sleepycat \', \'\') ) ) AS product_name_final, COALESCE( UPPER(CAST(p.CATEGORY AS STRING)), UPPER(CAST(z.sku_category AS STRING)) ) AS product_category, COALESCE( UPPER(CAST(p.sub_category AS STRING)), UPPER(z.SKU_Sub_Category) ) AS sub_category, p.skucode as commonsku, p.EAN AS EAN_sku_master, p.GST_Rate, p.HSN, p.product_image_url, p.cogs FROM sleepycat_db.maplemonk.sleepycat_zepto_fact_items_intermediate z LEFT JOIN ( SELECT * FROM sleepycat_db.maplemonk.gs_mapping_qc_sku_mapping WHERE lower(platform) = \'zepto\' QUALIFY ROW_NUMBER() OVER (PARTITION BY priority ORDER BY 1) = 1 ) qc ON upper(qc.priority) = (z.ean) LEFT JOIN ( SELECT * FROM ( SELECT EAN, skucode, category, sub_category, GST_Rate, name, HSN, Product_Launch_date, product_image_url, cogs, ROW_NUMBER() OVER ( PARTITION BY upper(skucode) ORDER BY LENGTH(COALESCE(upper(skucode), \'\')) DESC ) AS rw FROM sleepycat_db.maplemonk.zepto_SKU_Master ) WHERE rw = 1 ) p ON LOWER(qc.\"Master SKU Code\") = LOWER(p.skucode) left join (select * from (select sku, date, taxable_value::float taxable_value, row_number() over (partition by sku, date order by 1) rw from sleepycat_db.maplemonk.gs_qc_taxable where lower(portal) = \'zepto\' )where rw = 1 ) tv on lower(qc.\"Master SKU Code\") = lower(tv.sku) and date_trunc(month,z.ordeR_Date) = tv.date ;",
                    "transaction": true
                }
            ) }}
            with sample_data as (

                select * from SLEEPYCAT_DB.information_schema.databases
            ),
            
            final as (
                select * from sample_data
            )
            select * from final
            